input.command:
cd /work; psql -q -v ON_ERROR_STOP=1 <<'EOF'
INSERT INTO orders SELECT 9999992,customer_id,'2026-01-15','COMPLETED',0 FROM customers LIMIT 1;
-- lowest item id (9999002) is category B product; higher id (9999001 would be lower) -> use ids so the first line is the 2nd inserted
INSERT INTO order_items SELECT 9999002,9999992,product_id,2,10 FROM (SELECT product_id FROM products WHERE category=(SELECT category FROM products ORDER BY product_id LIMIT 1) LIMIT 1) a;
INSERT INTO order_items SELECT 9999003,9999992,product_id,5,100 FROM (SELECT product_id FROM products WHERE category<>(SELECT category FROM products ORDER BY product_id LIMIT 1) LIMIT 1) a;
INSERT INTO order_items SELECT 9999001,9999992,product_id,3,7 FROM (SELECT product_id FROM products WHERE category<>(SELECT category FROM products ORDER BY product_id LIMIT 1) ORDER BY product_id DESC LIMIT 1) a;
EOF
psql -q -v ON_ERROR_STOP=1 -f etl.sql
psql -c "select p.category, oi.order_item_id, oi.quantity*oi.unit_price from order_items oi join products p using(product_id) where order_id=9999992 order by 2" -c "select * from etl_run_log order by run_id desc limit 1"
psql -c "select * from dash_revenue_by_category where month='2026-01' and revenue in (21) or (month='2026-01' and units_sold=3)"
psql -qc "delete from order_items where order_id=9999992; delete from orders where order_id=9999992" && psql -q -v ON_ERROR_STOP=1 -f etl.sql && psql -tc "select mismatch from etl_run_log order by run_id desc limit 1"

